const isChild = location.search.indexOf('child=1') !== -1;
// Roblox's VideoFrame fallback permits two simultaneous clips in this family.
const playsClip = !isChild || new URLSearchParams(location.search).get('n') === '1';
const initialURL = location.href;
const initialTitle = 'The Annoying Site';
const popupLimit = 4;
const initialPopupCount = 2;
const popupJumpInterval = 100;
let running = false;
let popupSequence = 0;
let popups = [];
let intervals = [];
let holdTimer = null;
let holdStarted = 0;
let tick = 0;
let lastError = '';
let stream = null;
let cameraGeneration = 0;
let cameraPending = false;
let audioMessage = 'Ton aus';
let videoMessage = 'Video aus';
let mediaGeneration = 0;
const titles = ['Du bist ja immer noch da.', 'Nur noch ein kleines Fenster.', 'Die Katze sagt hallo.', 'Ganz harmlos. Versprochen.'];

function element(id) { return document.getElementById(id); }
function text(id, value) { element(id).textContent = value; }
function onClick(id, handler) { element(id).addEventListener('click', handler); }
function message(value) { text('run-status', value); }
function errorText(error) { return error && error.message ? (error.name || 'Fehler') + ': ' + error.message : String(error); }
function fail(error) { lastError = errorText(error); message(lastError); }
function renderMedia() { text('media-status', audioMessage + ' · ' + videoMessage); }
function activePopups() {
  const active = [];
  popups.forEach(function (popup) {
    try { if (!popup.window.closed) active.push(popup); } catch (error) { lastError = errorText(error); }
  });
  popups = active;
  text('popup-count', popups.length + ' / ' + popupLimit + ' Fenster');
  return popups.length;
}
function cancelHold() {
  if (holdTimer !== null) clearInterval(holdTimer);
  holdTimer = null;
  holdStarted = 0;
  element('hold-progress').style.width = '0%';
}
function cleanCamera() {
  cameraGeneration += 1;
  cameraPending = false;
  const previous = stream;
  stream = null;
  if (previous) previous.getTracks().forEach(function (track) { track.stop(); });
  const preview = element('camera-preview');
  preview.pause();
  preview.srcObject = null;
  element('camera-frame').hidden = true;
  text('camera-button', 'Kamera');
}
function playMedia() {
  const generation = ++mediaGeneration;
  const clip = element('clip');
  const soundtrack = element('soundtrack');
  clip.muted = true;
  clip.loop = true;
  soundtrack.loop = true;
  soundtrack.volume = 0.12;
  soundtrack.muted = false;
  videoMessage = playsClip ? 'Video startet' : 'Standbild';
  audioMessage = isChild ? 'Ton im Hauptfenster' : 'Ton startet';
  text('sound-button', 'Ton aus');
  renderMedia();
  if (!playsClip) {
    clip.pause();
    element('video-placeholder').hidden = false;
    return;
  }
  try {
    const videoPlay = clip.play();
    if (videoPlay && typeof videoPlay.then === 'function') videoPlay.then(function () {
      if (!running || generation !== mediaGeneration) return;
      videoMessage = 'Video läuft';
      element('video-placeholder').hidden = true;
      renderMedia();
    }, function (error) {
      if (!running || generation !== mediaGeneration) return;
      videoMessage = 'Video nicht verfügbar (' + errorText(error) + ')';
      element('video-placeholder').hidden = false;
      renderMedia();
    });
  } catch (error) { videoMessage = errorText(error); renderMedia(); }
  if (isChild) return;
  try {
    const audioPlay = soundtrack.play();
    if (audioPlay && typeof audioPlay.then === 'function') audioPlay.then(function () {
      if (!running || generation !== mediaGeneration) return;
      audioMessage = 'Ton läuft';
      renderMedia();
    }, function (error) {
      if (!running || generation !== mediaGeneration) return;
      audioMessage = 'Ton nicht verfügbar (' + errorText(error) + ')';
      renderMedia();
    });
  } catch (error) { audioMessage = errorText(error); renderMedia(); }
}
function stopMedia() {
  mediaGeneration += 1;
  const ids = ['clip', 'soundtrack'];
  ids.forEach(function (id) {
    const media = element(id);
    media.muted = true;
    media.pause();
    try { media.currentTime = 0; } catch (error) { lastError = errorText(error); }
  });
  audioMessage = 'Ton aus';
  videoMessage = 'Video aus';
  element('video-placeholder').hidden = false;
  renderMedia();
}
function requestCamera() {
  if (!running || isChild) return;
  if (stream || cameraPending) {
    cleanCamera();
    text('camera-status', 'Kamera gestoppt.');
    return;
  }
  if (!navigator.mediaDevices || typeof navigator.mediaDevices.getUserMedia !== 'function') {
    text('camera-status', 'Diese Umgebung stellt keine Kamera bereit.');
    return;
  }
  const generation = ++cameraGeneration;
  cameraPending = true;
  text('camera-button', 'Anfrage abbrechen');
  text('camera-status', 'Bitte beantworte die Kameraanfrage mit Zulassen oder Blockieren.');
  try {
    window.focus();
    navigator.mediaDevices.getUserMedia({ video: true }).then(function (result) {
      if (!running || generation !== cameraGeneration) {
        result.getTracks().forEach(function (track) { track.stop(); });
        return;
      }
      cameraPending = false;
      stream = result;
      const preview = element('camera-preview');
      preview.srcObject = result;
      element('camera-frame').hidden = false;
      text('camera-button', 'Kamera aus');
      text('camera-status', 'Die Kamera läuft.');
      result.getVideoTracks().forEach(function (track) {
        track.addEventListener('ended', function () {
          if (stream !== result) return;
          cleanCamera();
          text('camera-status', 'Die Kameraquelle ist nicht mehr verfügbar.');
        });
      });
      const playback = preview.play();
      if (playback && typeof playback.catch === 'function') playback.catch(function (error) {
        if (stream !== result) return;
        cleanCamera();
        text('camera-status', errorText(error));
      });
    }, function (error) {
      if (generation !== cameraGeneration) return;
      cameraPending = false;
      text('camera-button', 'Kamera');
      text('camera-status', errorText(error));
    });
  } catch (error) {
    cameraPending = false;
    text('camera-button', 'Kamera');
    text('camera-status', errorText(error));
  }
}
function openPopup() {
  if (!running || isChild) return null;
  if (activePopups() >= popupLimit) {
    message('Vier Fenster reichen erst einmal. Schließe eines, um ein neues zu öffnen.');
    return null;
  }
  popupSequence += 1;
  const base = initialURL.split('?')[0].split('#')[0];
  const x = 50 + (popupSequence % 4) * 42;
  const y = 70 + (popupSequence % 4) * 32;
  let child = null;
  try {
    child = window.open(base + '?child=1&n=' + popupSequence, 'annoying_popup_' + popupSequence, 'popup,width=360,height=330,left=' + x + ',top=' + y);
  } catch (error) { fail(error); return null; }
  if (!child) { message('Das Zusatzfenster wurde vom Browser blockiert. Über „Noch ein Fenster“ erneut versuchen.'); return null; }
  popups.push({ window: child });
  activePopups();
  message('Die Katze hat ein eigenes Fenster.');
  return child;
}
function jumpWindows() {
  if (!running || isChild) return;
  activePopups();
  popups.forEach(function (popup) {
    try {
      const display = window.screen || {};
      const width = display.availWidth || display.width || window.innerWidth || 1000;
      const height = display.availHeight || display.height || window.innerHeight || 700;
      const left = display.availLeft || 0;
      const top = display.availTop || 0;
      const maxX = left + Math.max(0, width - (popup.window.outerWidth || 360));
      const maxY = top + Math.max(0, height - (popup.window.outerHeight || 330));
      const x = left + Math.floor(Math.random() * (maxX - left + 1));
      const y = top + Math.floor(Math.random() * (maxY - top + 1));
      popup.window.moveTo(x, y);
      if (!cameraPending) popup.window.focus();
    } catch (error) { lastError = errorText(error); }
  });
}
function changeAddress(push) {
  tick += 1;
  const url = initialURL.split('#')[0] + '#still-here-' + tick;
  try {
    if (push) history.pushState({ annoying: true, tick: tick }, '', url);
    else history.replaceState({ annoying: true, tick: tick }, '', url);
  } catch (error) { lastError = errorText(error); }
  document.title = (tick % 2 ? 'Hi there!' : initialTitle);
  text('show-title', titles[tick % titles.length]);
}
function showMessage() {
  if (!running || isChild) return;
  try {
    alert('Hi there! Die Katze wollte nur kurz hallo sagen.');
    if (running) message('Meldung geschlossen. Wir sind noch hier.');
  } catch (error) { fail(error); }
}
function toggleFullscreen() {
  if (!running || isChild) return;
  try {
    let result;
    if (document.fullscreenElement) result = document.exitFullscreen();
    else if (typeof element('activity').requestFullscreen === 'function') result = element('activity').requestFullscreen();
    else { message('Vollbild wird in dieser Umgebung nicht unterstützt.'); return; }
    if (result && typeof result.catch === 'function') result.catch(fail);
  } catch (error) { fail(error); }
}
function teardown(restoreURL) {
  running = false;
  cancelHold();
  intervals.forEach(function (timer) { clearInterval(timer); });
  intervals = [];
  cleanCamera();
  stopMedia();
  const owned = popups;
  popups = [];
  owned.forEach(function (popup) { try { if (!popup.window.closed) popup.window.close(); } catch (error) { lastError = errorText(error); } });
  activePopups();
  if (document.fullscreenElement) {
    try {
      const exit = document.exitFullscreen();
      if (exit && typeof exit.catch === 'function') exit.catch(function () {});
    } catch (error) { lastError = errorText(error); }
  }
  if (restoreURL && !isChild) {
    try { history.replaceState(null, '', initialURL); } catch (error) { lastError = errorText(error); }
  }
  document.title = initialTitle;
}
function stop() {
  teardown(true);
  element('activity').hidden = true;
  element('welcome').hidden = false;
  text('start-status', 'Alles gestoppt. Die Katze wartet, falls du noch einmal möchtest.');
  text('camera-status', 'Die Kamera ist aus.');
  if (isChild) { try { window.close(); } catch (error) { lastError = errorText(error); } }
}
function start() {
  if (running) return;
  cancelHold();
  running = true;
  tick = 0;
  lastError = '';
  element('welcome').hidden = true;
  element('activity').hidden = false;
  playMedia();
  if (isChild) {
    document.title = 'Noch eine Katze';
    text('stop-button', 'Schließen');
    text('show-title', 'Hallo aus dem Zusatzfenster!');
    message('Das Hauptfenster bewegt dieses Fenster.');
    return;
  }
  message('Los geht’s. Stop bleibt immer erreichbar.');
  popupSequence = 0;
  changeAddress(true);
  for (let i = 0; i < initialPopupCount; i += 1) openPopup();
