  intervals.push(setInterval(function () { if (running) changeAddress(false); }, 4000));
  intervals.push(setInterval(function () { if (running && !document.hidden) showMessage(); }, 30000));
  requestCamera();
}
onClick('start-button', start);
onClick('start-cat', start);
onClick('stop-button', stop);
onClick('popup-button', openPopup);
onClick('alert-button', showMessage);
onClick('fullscreen-button', toggleFullscreen);
onClick('camera-button', requestCamera);
onClick('brand-link', function (event) { event.preventDefault(); if (running && !isChild) changeAddress(true); });
onClick('sound-button', function () {
  if (!running || isChild) return;
  const soundtrack = element('soundtrack');
  soundtrack.muted = !soundtrack.muted;
  text('sound-button', soundtrack.muted ? 'Ton an' : 'Ton aus');
  audioMessage = soundtrack.muted ? 'Ton stumm' : 'Ton läuft';
  renderMedia();
});
element('clip').addEventListener('error', function () {
  if (!running) return;
  videoMessage = 'Video konnte nicht geladen werden.';
  element('video-placeholder').hidden = false;
  renderMedia();
});
element('soundtrack').addEventListener('error', function () {
  if (!running || isChild) return;
  audioMessage = 'Ton konnte nicht geladen werden.';
  renderMedia();
});
document.addEventListener('fullscreenchange', function () { text('fullscreen-button', document.fullscreenElement ? 'Vollbild aus' : 'Vollbild'); });
document.addEventListener('keydown', function (event) {
  if (running || isChild || (event.code !== 'Space' && event.key !== ' ')) return;
  const tag = event.target && event.target.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'BUTTON' || tag === 'SELECT') return;
  event.preventDefault();
  if (holdTimer !== null) return;
  holdStarted = Date.now();
  holdTimer = setInterval(function () {
    const progress = Math.min(1, (Date.now() - holdStarted) / 3000);
    element('hold-progress').style.width = Math.round(progress * 100) + '%';
    if (progress >= 1) start();
  }, 50);
});
document.addEventListener('keyup', function (event) { if (event.code === 'Space' || event.key === ' ') cancelHold(); });
window.addEventListener('blur', cancelHold);
document.addEventListener('visibilitychange', function () { if (document.hidden) cancelHold(); });
window.addEventListener('beforeunload', function (event) {
  if (running && !isChild && element('leave-guard').checked) { event.preventDefault(); event.returnValue = ''; }
});
window.addEventListener('pagehide', function () { teardown(false); });
window.addEventListener('unload', function () { teardown(false); });
window.addEventListener('popstate', function () {
  if (!running || isChild) return;
  teardown(false);
  element('activity').hidden = true;
  element('welcome').hidden = false;
  text('start-status', 'Zurück zur Startseite. Alles ist gestoppt.');
});
window.annoyingSite = {
  start: start,
  stop: stop,
  openPopup: openPopup,
  showMessage: showMessage,
  requestCamera: requestCamera,
  getState: function () {
    return { running: running, child: isChild, popupCount: activePopups(), cameraActive: stream !== null, fullscreen: !!document.fullscreenElement, tick: tick, lastError: lastError };
  }
};
if (isChild) { document.body.classList.add('child'); start(); }

