  }
}

files.styles.css:
* { box-sizing: border-box; }
body { margin: 0; background: #fff; color: #242424; font: 15px/1.5 Arial, Helvetica, sans-serif; }
button, input { font: inherit; }
button { border: 1px solid #c9c9c9; border-radius: 4px; background: #fff; color: #242424; padding: 7px 11px; cursor: pointer; }
button:hover { border-color: #999; background: #f0f0f0; }
button:active { background: #e0e0e0; }
button:focus-visible, a:focus-visible { outline: 2px solid #6255b8; outline-offset: 3px; }
a { color: inherit; }
[hidden] { display: none; }
#welcome { max-width: 660px; margin: 0 auto; padding: 58px 22px 22px; text-align: center; }
h1 { font-size: 68px; line-height: 1.1; margin: 0 0 22px; letter-spacing: -2px; }
.cat-button { display: block; width: 256px; height: 238px; margin: 0 auto 12px; padding: 6px 10px; border: 0; background: transparent; border-radius: 12px; }
.cat-button:hover { background: #f8f6fb; }
.cat-button:active { background: #eeebf5; }
.cat-button img { display: block; }
.invitation { font-size: 21px; margin: 14px 0 18px; }
.start-button { padding: 10px 32px; border-color: #393939; background: #242424; color: #fff; font-weight: bold; }
.start-button:hover { background: #424242; border-color: #424242; }
.start-button:active { background: #080808; }
.space-hint { color: #777; font-size: 13px; margin: 16px 0 9px; }
.hold-track { width: 150px; height: 3px; margin: 0 auto; background: #eee; overflow: hidden; border-radius: 2px; }
#hold-progress { width: 0; height: 3px; background: #6255b8; }
.start-status { min-height: 38px; max-width: 400px; margin: 19px auto 0; color: #999; font-size: 12px; }
footer { padding: 22px 16px; text-align: center; color: #999; font-size: 11px; }
footer span { margin: 0 7px; }
.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 18px; border-bottom: 1px solid #ddd; background: #fff; }
.brand { flex-shrink: 0; font-size: 20px; font-weight: bold; letter-spacing: -1px; text-decoration: none; }
.toolbar-buttons { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 6px; }
.toolbar-buttons button { font-size: 13px; }
.toolbar .stop-button { border-color: #b52525; background: #b52525; color: #fff; font-weight: bold; }
.toolbar .stop-button:hover { background: #961c1c; border-color: #961c1c; }
.toolbar .stop-button:active { background: #721414; }
.show { max-width: 900px; margin: 0 auto; padding: 22px 22px 0; }
.show-heading { margin-bottom: 15px; }
h2 { margin: 0 0 4px; font-size: 28px; line-height: 1.2; letter-spacing: -.6px; }
#run-status { margin: 4px 0; color: #777; font-size: 13px; }
.screen { position: relative; width: 100%; height: 390px; overflow: hidden; background: #f1edf8; border: 1px solid #e1dce9; border-radius: 5px; }
#clip { display: block; width: 100%; height: 100%; object-fit: cover; background: #f1edf8; }
.video-placeholder { position: absolute; left: 0; right: 0; top: 42px; text-align: center; }
.video-placeholder img { display: block; margin: 0 auto; }
.video-placeholder p { color: #746b82; font-size: 13px; margin-top: 12px; }
.camera-frame { position: absolute; right: 12px; bottom: 12px; width: 210px; height: 139px; border: 3px solid #fff; background: #1c1c1c; border-radius: 4px; overflow: hidden; }
#camera-preview { display: block; width: 100%; height: 112px; object-fit: cover; background: #1c1c1c; }
.camera-frame span { display: block; padding: 2px 5px; font-size: 11px; background: #fff; color: #333; }
.status-line { display: flex; justify-content: space-between; gap: 14px; margin-top: 11px; color: #777; font-size: 12px; }
#popup-count { flex-shrink: 0; }
.camera-status { margin: 8px 0 12px; color: #777; font-size: 12px; }
.guard-label { display: block; margin-top: 14px; color: #555; font-size: 12px; }
.guard-label input { vertical-align: middle; margin: 0 5px 2px 0; }
.small-print { margin: 8px 0 0; color: #999; font-size: 11px; }
#activity:fullscreen { width: 100%; height: 100%; background: #fff; overflow: auto; }
#activity:fullscreen .show { max-width: 1100px; }
#activity:fullscreen .screen { height: 60vh; }
body.child .toolbar { padding: 8px 10px; }
body.child .toolbar-buttons button { display: none; }
body.child .toolbar-buttons #stop-button { display: block; }
body.child .brand { font-size: 17px; }
body.child .show { padding: 12px 10px 0; }
body.child .show-heading { margin-bottom: 10px; }
body.child h2 { font-size: 20px; }
body.child .screen { height: 150px; }
body.child .video-placeholder { top: 5px; }
body.child .video-placeholder img { width: 112px; height: 106px; }
body.child .video-placeholder p { margin: 2px 0; font-size: 11px; }
body.child #popup-count, body.child #camera-status, body.child #guard-label, body.child #safety-note, body.child #running-footer { display: none; }
body.child .status-line { margin-top: 6px; }
@media (max-width: 620px) {
  #welcome { padding-top: 38px; }
  h1 { font-size: 55px; }
  .toolbar { align-items: flex-start; flex-wrap: wrap; padding: 10px; }
  .toolbar-buttons { justify-content: flex-start; }
  .toolbar-buttons button { padding: 6px 9px; }
  .show { padding: 17px 12px 0; }
  h2 { font-size: 25px; }
  .screen { height: 285px; }
  .video-placeholder { top: 30px; }
  .camera-frame { width: 160px; height: 111px; }
  #camera-preview { height: 84px; }
  .status-line { flex-wrap: wrap; gap: 3px; }
}

