(function () {
  'use strict';

  var storageKey = 'bytebude.v1.';
  function read(key, fallback) {
    try { var raw = localStorage.getItem(storageKey + key); return raw === null ? fallback : JSON.parse(raw); }
    catch (error) { return fallback; }
  }
