  visits = typeof visits === 'number' && isFinite(visits) && visits >= 0 ? Math.min(Math.floor(visits) + 1, 999999) : 1;
  byId('visit-count').textContent = String(visits).padStart(6, '0');
  if (!save('visits', visits)) byId('visit-note').textContent = 'Speicherung nicht verfügbar. Der Zähler gilt nur für diese Sitzung.';
  byId('today').textContent = new Date().toLocaleDateString('de-DE', {day: '2-digit', month: '2-digit', year: 'numeric'});

  var night = read('night', false) === true;
