      else if (event.key === 'ArrowLeft') next = (index + tabs.length - 1) % tabs.length;
      else if (event.key === 'Home') next = 0;
      else if (event.key === 'End') next = tabs.length - 1;
      else return;
      event.preventDefault(); selectTab(tabs[next], true);
    });
  });
  document.querySelector('a[href="#ueber"]').addEventListener('click', function () { selectTab(byId('tab-about'), false); });

  var finds = [
    ['Die perfekte Mix-CD.', 'Zwölf Songs, ein selbst gemaltes Cover und ein Titel mit viel zu vielen Ausrufezeichen. Besser als jede automatische Playlist.'],
    ['Das Geräusch einer neuen Nachricht.', 'Nur ein kleines „Oh-oh“ aus dem Lautsprecher. Und plötzlich musste man ganz dringend wieder an den Rechner.'],
    ['Eine Diskette mit Geheimnissen.', '1,44 Megabyte Platz. Genug für die erste Homepage, ein paar Texte und eine Datei namens wirklich_final_3.txt.'],
    ['Der Ordner voller Urlaubsbilder.', 'Kleine Auflösung, rote Augen und ein Datum in der Ecke. Trotzdem erkennt man sofort, wie sich dieser Sommer angefühlt hat.'],
    ['Die eigene kleine Linkliste.', 'Keine Empfehlungen von einem Algorithmus. Einfach fünf Seiten, die jemand so gut fand, dass er sie dir zeigen wollte.']
  ];
  var find = 0;
  byId('next-find').addEventListener('click', function () {
    find = (find + 1) % finds.length;
    byId('find-number').textContent = 'DISKETTE ' + String(find + 1).padStart(2, '0') + ' / 05';
    byId('find-title').textContent = finds[find][0];
    byId('find-text').textContent = finds[find][1];
  });

  var choices = {chat: 'Im Chat versacken', music: 'Eine CD brennen', games: 'Noch eine Runde', outside: 'Draußen bleiben'};
