    if (!chosen) { byId('poll-result').textContent = 'Bitte wähle erst eine Antwort.'; return; }
    paintPoll(chosen.value);
    if (!save('poll', chosen.value)) byId('poll-result').textContent += ' Speicherung nicht verfügbar.';
  });

  var savedGuests = read('guests', []);
  var guests = Array.isArray(savedGuests) ? savedGuests.slice(0, 12).filter(function (entry) {
    return entry && typeof entry.name === 'string' && entry.name.trim() && entry.name.length <= 24 && typeof entry.message === 'string' && entry.message.trim() && entry.message.length <= 180 && typeof entry.date === 'string' && entry.date.length <= 32;
  }) : [];
  var ownEntries = [];
  function addGuest(entry) {
    var container = byId('guest-entries');
    var article = document.createElement('article'); article.className = 'guest-entry';
    var heading = document.createElement('div'); heading.className = 'guest-heading';
    var name = document.createElement('strong'); name.textContent = entry.name;
    var date = document.createElement('span'); date.textContent = entry.date + ' / Lokal';
    var message = document.createElement('p'); message.textContent = entry.message;
    heading.appendChild(name); heading.appendChild(date); article.appendChild(heading); article.appendChild(message);
    container.insertBefore(article, container.children[0] || null); ownEntries.unshift(article);
    if (ownEntries.length > 12) ownEntries.pop().remove();
  }
  function paintGuestCount() {
    byId('guest-count').textContent = String(guests.length + 2) + ' Einträge';
  }
  guests.slice().reverse().forEach(addGuest); paintGuestCount();
  byId('guest-message').addEventListener('input', function () { byId('message-length').textContent = String(this.value.length) + ' / 180 Zeichen'; });
  byId('guest-form').addEventListener('submit', function (event) {
    event.preventDefault();
    var name = byId('guest-name').value.trim(); var message = byId('guest-message').value.trim();
    if (!name || !message) { byId('guest-status').textContent = 'Bitte gib deinen Namen und einen Gruß ein.'; return; }
    if (name.length > 24 || message.length > 180) { byId('guest-status').textContent = 'Dein Name darf 24, dein Gruß 180 Zeichen haben.'; return; }
    var entry = {name: name, message: message, date: new Date().toLocaleDateString('de-DE')};
    guests.unshift(entry); guests = guests.slice(0, 12);
    var stored = save('guests', guests); addGuest(entry); paintGuestCount();
    byId('guest-form').reset(); byId('message-length').textContent = '0 / 180 Zeichen';
    byId('guest-status').textContent = stored ? 'Danke für deinen Gruß! Er wurde auf deinem Gerät gespeichert.' : 'Danke für deinen Gruß! Er bleibt in dieser Sitzung sichtbar; Speicherung ist gerade nicht verfügbar.';
  });
}());

files.styles.css:
:root { color-scheme: light; --page: #f5f4ec; --panel: #ffffff; --ink: #243341; --muted: #63717d; --blue: #144ea6; --line: #b1b7ba; --chrome: #e5e5df; --title: #164f8d; }
* { box-sizing: border-box; }
html { scroll-padding-top: 12px; }
body { margin: 0; padding: 28px 16px; background: #176e7c; background-image: linear-gradient(135deg, #20828b, #153e61); color: var(--ink); font-family: Verdana, Arial, sans-serif; font-size: 12px; line-height: 1.65; }
a { color: var(--blue); text-decoration: underline; }
