button, input, textarea { font-family: Verdana, Arial, sans-serif; font-size: 12px; }
button { cursor: pointer; }
a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible, summary:focus-visible { outline: 2px solid #df6a24; outline-offset: 3px; }
[hidden] { display: none !important; }
p { margin: 0 0 12px; }
h1, h2, h3 { margin: 0; }
