.header-stickers { display: flex; gap: 9px; }
.sticker { display: block; padding: 10px 11px; background: #176984; border: 2px solid #08445d; color: white; font: bold 11px/1.35 "Courier New", monospace; text-align: center; }
.sticker.yellow { background: #f8ca58; color: #744822; border-color: #bd932c; }
.top-navigation { display: flex; gap: 3px; padding: 7px 10px 0; background: #d6dedc; border-bottom: 3px solid #176984; }
.top-navigation a, .top-navigation button { display: block; padding: 6px 16px; border: 1px solid #9aadb1; border-bottom: 0; background: #edf1e9; color: #2a536d; font-weight: bold; text-decoration: none; white-space: nowrap; }
.top-navigation .active { color: white; background: #176984; border-color: #176984; }
.top-navigation a:hover, .top-navigation button:hover { background: #fff8cf; color: #714b24; }
.top-navigation button { margin-left: auto; font-size: 11px; }
.news-ticker { display: flex; align-items: center; gap: 12px; padding: 8px 14px; background: #fff5c9; border-bottom: 1px solid #d8c483; font-size: 11px; }
.ticker-label { color: #a64224; font: bold 11px "Courier New", monospace; white-space: nowrap; }
.news-ticker p { margin: 0; }
.page-columns { display: grid; grid-template-columns: 153px minmax(0, 1fr) 187px; gap: 12px; padding: 15px 12px 24px; align-items: start; }
.left-column, .right-column, main { min-width: 0; }
