.retro-button:hover { background: #fff1be; color: #783c1d; }
.retro-button:active { border-style: inset; }
.retro-button.primary { background: #e2ecf5; border-color: #9fb5c8; color: #134b87; }
.tab-bar { display: flex; gap: 3px; padding: 9px 10px 0; border-bottom: 1px solid #a6b1b5; background: var(--chrome); }
.tab-bar button { padding: 5px 9px; border: 1px solid #a6b1b5; border-bottom: 0; color: var(--ink); background: #d5dcd9; font-size: 10px; }
