.tab-bar button:hover { color: #934a23; }
.tab-content { min-height: 165px; }
.news-entry { display: grid; grid-template-columns: 69px minmax(0, 1fr); gap: 12px; padding: 4px 0 11px; margin-bottom: 10px; border-bottom: 1px dotted #c2cbd0; }
.news-entry:last-child { border-bottom: 0; margin-bottom: 0; padding-bottom: 0; }
.news-entry time { color: #49687b; font: 10px "Courier New", monospace; padding-top: 3px; }
.news-entry h3 { font-size: 12px; margin-bottom: 4px; color: #184d85; }
.news-entry p { margin: 0; font-size: 11px; }
.plain-list { margin: 8px 0 12px; padding-left: 19px; }
.plain-list li { margin-bottom: 6px; }
.section-intro { font-size: 11px; }
.games-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 12px; }
.game-card { border: 1px solid #bcc8cb; background: #f4f7f5; }
.game-preview { display: flex; height: 90px; align-items: center; justify-content: center; gap: 6px; border-bottom: 1px solid #c2c4c2; }
.memory-preview { background: #e3ddeb; }
.memory-preview span { display: inline-block; width: 31px; height: 39px; background: #6a508a; border: 2px outset #9c84b4; color: #e8dbf8; font: bold 22px/35px "Courier New", monospace; text-align: center; }
.memory-preview .revealed { color: #614282; background: #faf5e7; border-color: #cabed4; }
.hangman-preview { background: #e1ebdf; flex-direction: column; gap: 8px; }
.word-preview { color: #28605c; font: bold 23px "Courier New", monospace; letter-spacing: 2px; }
.letter-preview { color: #597265; font: 12px "Courier New", monospace; letter-spacing: 3px; }
.game-copy { padding: 11px; }
