.find-footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 6px; }
.diary-entry { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 12px; }
.diary-date { align-self: start; padding: 5px 2px; background: #f2e6ca; border: 1px solid #cbbea0; text-align: center; }
.diary-date strong { display: block; color: #945d32; font: bold 27px/1.1 Georgia, serif; }
.diary-date span { font: 9px "Courier New", monospace; }
.diary-entry h3 { margin-bottom: 8px; color: #154977; }
.diary-entry p { font-size: 11px; }
