.guest-form-footer { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.form-status { min-height: 17px; margin: 7px 0 13px; color: #427351; font-size: 10px; }
.guest-entry { border-top: 1px dotted #bdc8cf; padding: 11px 0; }
