.night .tab-bar button.selected { background: var(--panel); }
.night .poll-result, .night .form-status { color: #a0d5b0; }
@media (max-width: 870px) { body { padding: 16px 10px; } .page-columns { grid-template-columns: 140px minmax(0, 1fr); } .right-column { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; } .right-column .window { margin-bottom: 0; } .webring, .side-quote { margin: 0; } .header-stickers { gap: 6px; } .sticker { padding: 8px; } }
@media (max-width: 580px) { body { padding: 10px 7px; } .website { border-width: 2px; box-shadow: 3px 3px 0 #0a394e; } .utility-bar { padding: 5px 8px; font-size: 9px; } .utility-bar span:last-child { display: none; } .masthead { padding: 20px 14px; } .logo { font-size: 40px; } .logo small { font-size: 19px; } .masthead p { max-width: 225px; font-size: 10px; line-height: 1.5; } .header-stickers .sticker:first-child { display: none; } .top-navigation { flex-wrap: wrap; padding: 6px 5px 0; } .top-navigation a, .top-navigation button { padding: 5px 8px; font-size: 10px; } .news-ticker { padding: 8px; gap: 7px; font-size: 10px; } .ticker-label { font-size: 9px; } .page-columns { display: flex; flex-direction: column; padding: 12px 8px; gap: 0; } main, .left-column, .right-column { width: 100%; } main { order: 0; } .right-column { order: 1; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; margin-bottom: 14px; } .right-column .window:nth-child(3) { grid-column: 1 / -1; } .right-column .side-quote { display: none; } .left-column { order: 2; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; } .left-column .window { margin-bottom: 0; } .badge-wall { grid-template-columns: 1fr 1fr; align-content: start; gap: 7px; margin: 0; } .web-badge { width: 100%; max-width: 94px; min-width: 0; font-size: 8px; } .construction { grid-column: 1 / -1; margin: 8px 0; } .welcome-window .window-body { padding: 14px; } .welcome-window h2 { font-size: 23px; } .welcome-links, .find-footer { flex-wrap: wrap; gap: 9px; } .window-title span { font-size: 8px; } .game-preview { gap: 4px; } .memory-preview span { width: 25px; height: 34px; font-size: 19px; line-height: 30px; } .game-copy { padding: 9px; } .game-copy p { min-height: 70px; } .tab-bar { padding: 7px 6px 0; gap: 2px; } .tab-bar button { padding: 5px 6px; font-size: 9px; } .news-entry { gap: 8px; grid-template-columns: 64px minmax(0, 1fr); } .guest-heading { flex-wrap: wrap; gap: 2px; } .footer { padding: 13px; } .status-bar { flex-wrap: wrap; font-size: 8px; } .status-bar span:last-child { display: none; } }

