(() => {
  'use strict';
  const byId = id => document.getElementById(id);
  const category = byId('category');
  const alphabet = Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÜ');
  const categories = {
    nature: { name: 'Natur & Tiere', words: ['SONNENBLUME', 'REGENBOGEN', 'SCHMETTERLING', 'EICHHÖRNCHEN', 'WASSERFALL', 'LIBELLE', 'WALDBODEN', 'SEESTERN'] },
    places: { name: 'Orte & unterwegs', words: ['BAHNHOF', 'LEUCHTTURM', 'BÜCHEREI', 'SPIELPLATZ', 'BERGHÜTTE', 'MARKTPLATZ', 'GARTEN', 'INSEL'] },
    things: { name: 'Dinge des Alltags', words: ['TASCHENLAMPE', 'SCHLÜSSEL', 'REGENSCHIRM', 'BÜCHERREGAL', 'KOPFHÖRER', 'WECKER', 'BLEISTIFT', 'FAHRRAD'] },
    food: { name: 'Essen & Trinken', words: ['ERDBEERE', 'PFANNKUCHEN', 'ZIMTSCHNECKE', 'KARTOFFEL', 'APFELSAFT', 'KIRSCHEN', 'MÜSLI', 'SCHOKOLADE'] }
  };
  const storageKey = 'spielraum.hangman.records.v1';
  const keys = {};
  const slots = [];
  let word = '';
  let guessed = {};
  let mistakes = 0;
  let hintUsed = false;
  let phase = 'playing';
  let wins = 0;
  let streak = 0;
  let bestStreak = 0;
  let storageAvailable = true;

  function text(id, value) {
    const element = byId(id);
    if (element.textContent !== value) element.textContent = value;
  }
  function validCount(value) { return Number.isInteger(value) && value >= 0 && value <= 10000000; }
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
    if (saved && typeof saved === 'object' && validCount(saved.wins) && validCount(saved.bestStreak) && saved.bestStreak <= saved.wins) {
      wins = saved.wins; bestStreak = saved.bestStreak;
    }
  } catch (error) { storageAvailable = false; }

  function updateRecord() {
    text('wins', String(wins));
    text('streak', String(streak));
    text('best-streak', bestStreak + (bestStreak === 1 ? ' Wort am Stück.' : ' Wörter am Stück.'));
    text('record-detail', wins === 0 ? 'Deine beste Serie wartet auf die erste Runde.' : wins + (wins === 1 ? ' Wort insgesamt gelöst. Das nächste wartet schon.' : ' Wörter insgesamt gelöst. Das nächste wartet schon.'));
    text('storage-note', storageAvailable ? 'Deine Statistik bleibt für die nächste Pause gespeichert.' : 'Speichern ist gerade nicht verfügbar. Du kannst trotzdem spielen.');
  }
  function saveRecord() {
    try { localStorage.setItem(storageKey, JSON.stringify({ wins, bestStreak })); }
    catch (error) { storageAvailable = false; }
    updateRecord();
  }
  function setKey(letter, correct) {
    const key = keys[letter];
    key.disabled = true;
    key.classList.add(correct ? 'is-correct' : 'is-wrong');
    key.setAttribute('aria-label', letter + (correct ? ': im Wort enthalten' : ': nicht im Wort enthalten'));
  }
  function paintWord() {
    const spoken = [];
    for (let i = 0; i < word.length; i += 1) {
      const known = Boolean(guessed[word[i]]);
      const missing = !known && phase === 'lost';
      const value = known || missing ? word[i] : '';
      const slot = slots[i];
      if (slot.textContent !== value) slot.textContent = value;
      slot.classList.toggle('is-known', known);
      slot.classList.toggle('is-missing', missing);
      spoken.push(known || missing ? word[i] : 'unbekannt');
    }
    byId('word').setAttribute('aria-label', 'Gesuchtes Wort: ' + spoken.join(', '));
  }
  function solved() {
    for (let i = 0; i < word.length; i += 1) if (!guessed[word[i]]) return false;
    return true;
  }
  function finish(won) {
    phase = won ? 'won' : 'lost';
    if (won) { wins += 1; streak += 1; bestStreak = Math.max(bestStreak, streak); }
    else streak = 0;
    for (const letter of alphabet) if (!keys[letter].disabled) keys[letter].disabled = true;
    byId('hint').disabled = true;
    paintWord();
    text('result-kicker', won ? 'Wort gefunden!' : 'Das nächste klappt.');
    text('result-title', won ? 'Gut kombiniert.' : 'Ein neuer Gedanke?');
    text('result-summary', won ? word + ' — mit ' + mistakes + (mistakes === 1 ? ' Fehlversuch' : ' Fehlversuchen') + (hintUsed ? ' und einem kleinen Tipp.' : ', ganz ohne Tipp.') : 'Das gesuchte Wort war ' + word + '. Mit dem nächsten Wort beginnt eine neue Serie.');
    byId('result').classList.toggle('is-lost', !won);
    byId('result').hidden = false;
    text('status', won ? 'Gefunden! ' + word + '. Schön gespielt.' : 'Sechs Fehlversuche. Das Wort war ' + word + '.');
    saveRecord();
    byId('new-round').focus();
  }
  function guess(letter, fromHint) {
    if (phase !== 'playing' || !keys[letter] || guessed[letter]) return;
    guessed[letter] = true;
    const correct = word.includes(letter);
    setKey(letter, correct);
    if (correct) {
      paintWord();
      if (solved()) { finish(true); return; }
      text('status', fromHint ? 'Dein Tipp: ' + letter + '. Jetzt bist du wieder dran.' : letter + ' ist dabei! Welcher Buchstabe kommt als Nächstes?');
    } else {
      mistakes += 1;
      text('mistakes', mistakes + ' / 6');
      byId('drawing').setAttribute('src', 'assets/stage-' + mistakes + '.svg');
      byId('drawing').alt = mistakes + (mistakes === 1 ? ' Fehlversuch. ' : ' Fehlversuche. ') + (6 - mistakes) + (mistakes === 5 ? ' Versuch bleibt.' : ' Versuche bleiben.');
      if (mistakes === 6) { finish(false); return; }
      text('status', letter + ' ist leider nicht dabei. Noch ' + (6 - mistakes) + (mistakes === 5 ? ' Fehlversuch bleibt.' : ' Fehlversuche bleiben.'));
    }
  }
  function newRound() {
    const selected = category.value;
    const choices = [];
    for (const name of Object.keys(categories)) {
      if (selected !== 'all' && selected !== name) continue;
      for (const value of categories[name].words) if (value !== word) choices.push({ word: value, category: name });
    }
    if (choices.length === 0) { category.value = 'all'; newRound(); return; }
    const next = choices[Math.floor(Math.random() * choices.length)];
    word = next.word; guessed = {}; mistakes = 0; hintUsed = false; phase = 'playing';
    for (const letter of alphabet) {
      const key = keys[letter];
      if (key.disabled) key.disabled = false;
      key.classList.remove('is-correct', 'is-wrong');
      key.setAttribute('aria-label', 'Buchstabe ' + letter + ' wählen');
    }
    while (slots.length < word.length) {
      const slot = document.createElement('span'); slot.className = 'letter'; slot.setAttribute('aria-hidden', 'true');
      slots.push(slot); byId('word').append(slot);
    }
    for (let i = 0; i < slots.length; i += 1) {
      slots[i].hidden = i >= word.length;
      if (i >= word.length && slots[i].textContent !== '') slots[i].textContent = '';
    }
    paintWord();
    text('word-category', categories[next.category].name);
    text('letter-count', word.length + ' Buchstaben');
    text('mistakes', '0 / 6');
    text('status', 'Wähle einen Buchstaben. Das Wort gehört dir.');
    text('hint-note', 'Ein Tipp pro Wort, wenn du ihn brauchst.');
    byId('hint').disabled = false;
    byId('result').hidden = true;
    if (byId('drawing').getAttribute('src') !== 'assets/stage-0.svg') byId('drawing').setAttribute('src', 'assets/stage-0.svg');
    byId('drawing').alt = 'Noch kein Fehlversuch. Sechs Versuche bleiben.';
    updateRecord();
  }
  function hint() {
    if (phase !== 'playing' || hintUsed) return;
    const remaining = [];
    for (const letter of Array.from(word)) if (!guessed[letter] && !remaining.includes(letter)) remaining.push(letter);
    if (remaining.length === 0) return;
    hintUsed = true; byId('hint').disabled = true;
    text('hint-note', 'Tipp benutzt. Das nächste Wort bringt einen neuen mit.');
    guess(remaining[Math.floor(Math.random() * remaining.length)], true);
  }
  for (const letter of alphabet) {
    const key = document.createElement('button'); key.type = 'button'; key.className = 'key'; key.textContent = letter;
    key.setAttribute('data-letter', letter); key.setAttribute('aria-label', 'Buchstabe ' + letter + ' wählen');
    key.addEventListener('click', () => guess(letter, false)); keys[letter] = key; byId('keyboard').append(key);
  }
  byId('new-round').addEventListener('click', newRound);
  byId('play-again').addEventListener('click', newRound);
  byId('hint').addEventListener('click', hint);
  category.addEventListener('change', newRound);
  document.addEventListener('keydown', event => {
    if (event.ctrlKey || event.altKey || event.metaKey || event.repeat || event.isComposing) return;
    const target = event.target;
    if (target && (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return;
    if (event.key === 'Enter' && phase !== 'playing') {
      if (target && target.tagName === 'BUTTON') return;
      event.preventDefault(); newRound(); return;
    }
    const letter = event.key.toUpperCase();
    if (letter.length === 1 && keys[letter] && phase === 'playing') { event.preventDefault(); guess(letter, false); }
  });
  newRound();
})();

files.styles.css:
:root { color-scheme: light; }
* { box-sizing: border-box; }
body { margin: 0; background: #f5f2e9; color: #242e28; font: 15px/1.6 Arial, sans-serif; }
a { color: inherit; }
button, select { font: inherit; }
button { cursor: pointer; }
[hidden] { display: none !important; }
.container { width: calc(100% - 96px); max-width: 1080px; margin: 0 auto; }
.skip-link { position: absolute; left: 20px; top: -100px; z-index: 20; background: #283d32; color: #fff; padding: 12px 18px; }
.skip-link:focus { top: 12px; }
a:focus-visible, button:focus-visible, select:focus-visible { outline: 3px solid #a14b31; outline-offset: 4px; }
.site-header { min-height: 84px; padding: 20px 48px; display: flex; align-items: center; justify-content: space-between; gap: 20px; border-bottom: 1px solid #d9ddd2; }
.brand { font-size: 28px; font-weight: 700; letter-spacing: -1.2px; text-decoration: none; }
.brand-dot { color: #b45939; }
.back-link { color: #586157; font-size: 13px; text-decoration: none; }
.back-link:hover { color: #a14b31; }
h1, h2, p { margin-top: 0; }
.eyebrow { font-size: 10px; letter-spacing: 1.7px; text-transform: uppercase; font-weight: 700; margin: 0 0 12px; }
.game-heading { padding: 34px 0 28px; display: flex; justify-content: space-between; gap: 24px; align-items: center; }
h1 { font-size: 44px; line-height: 1.12; letter-spacing: -1.8px; margin-bottom: 12px; }
.intro { color: #687063; font-size: 14px; margin-bottom: 0; max-width: 550px; }
.solo-tag { border: 1px solid #cdd4c7; border-radius: 22px; padding: 5px 12px; color: #687063; font-size: 11px; white-space: nowrap; }
.game-layout { display: grid; grid-template-columns: minmax(0, 1fr) 260px; gap: 36px; align-items: start; }
.toolbar { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px; margin-bottom: 20px; }
.category-label { font-size: 11px; color: #687063; }
select { display: block; background: #fffdf8; color: #283d32; border: 1px solid #bdc8b6; border-radius: 5px; padding: 8px 10px; min-width: 190px; max-width: 100%; margin-top: 5px; font-size: 13px; height: 38px; }
.small-button { background: #fffdf8; color: #283d32; border: 1px solid #bdc8b6; padding: 8px 12px; border-radius: 5px; min-height: 38px; font-size: 12px; transition: background-color .15s ease; }
.small-button:hover { background: #e6ebdf; }
.primary-button { background: #283d32; color: #fff8e9; border: 1px solid #283d32; padding: 12px 18px; border-radius: 5px; font-size: 13px; transition: background-color .15s ease; }
.primary-button:hover { background: #3d5446; }
.small-button:disabled { color: #8b9285; background: #eeefe6; cursor: default; }
.scoreboard { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border: 1px solid #d2d8c9; border-radius: 7px; background: #fffdf8; margin-bottom: 20px; padding: 12px 0; }
.scoreboard > div { padding: 0 18px; }
.scoreboard > div + div { border-left: 1px solid #e2e6d9; }
.score-label { display: block; color: #687063; font-size: 10px; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 2px; }
.scoreboard strong { display: block; font-size: 23px; line-height: 1.3; }
.puzzle-card { background: #fffdf8; border: 1px solid #d2d8c9; border-radius: 9px; overflow: hidden; }
.drawing-area { background: #dce5e9; padding: 18px 24px 0; }
.drawing-caption { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.drawing-caption .eyebrow { margin: 0; color: #47616a; }
.letters-note { font-size: 11px; color: #526973; white-space: nowrap; }
.drawing { display: block; width: 300px; max-width: 100%; height: auto; margin: 4px auto 0; }
.word-area { padding: 24px; }
.word { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
.letter { display: flex; align-items: center; justify-content: center; width: 32px; height: 42px; border-bottom: 2px solid #a9b8a4; background: #f1f3e9; border-radius: 4px 4px 0 0; font-size: 22px; line-height: 1; font-weight: 700; }
.letter.is-known { color: #283d32; background: #e3ecd9; border-color: #8ba17a; }
.letter.is-missing { color: #9e4d37; background: #f3e0d5; border-color: #b87760; }
.game-status { min-height: 40px; margin: 18px 0 0; font-size: 13px; color: #586157; text-align: center; }
.keyboard { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 7px; margin-top: 20px; }
.key { width: 100%; min-width: 0; min-height: 40px; padding: 6px 0; border: 1px solid #bdc8b6; border-radius: 5px; background: #fffdf8; color: #283d32; font-size: 14px; font-weight: 700; transition: background-color .15s ease; }
.key:hover { background: #e6ebdf; }
.key.is-correct, .key.is-correct:hover { color: #355035; background: #dce8d0; border-color: #a8bc98; cursor: default; }
.key.is-wrong, .key.is-wrong:hover { color: #9e4d37; background: #efdfd6; border-color: #d3b7a8; cursor: default; }
.key:disabled { cursor: default; }
.key:disabled:not(.is-correct):not(.is-wrong) { color: #93998d; background: #eeefe6; }
.game-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 18px; }
.hint-note { color: #687063; font-size: 11px; margin: 0; }
.game-sidebar { display: flex; flex-direction: column; gap: 18px; }
.tip-card, .record-card, .result-card { padding: 24px; border-radius: 8px; }
.tip-card { background: #e9c5b4; }
.tip-card h2, .record-card h2, .result-card h2 { font-size: 25px; line-height: 1.2; letter-spacing: -.8px; margin-bottom: 18px; }
.tip-card ol { padding-left: 18px; margin: 0 0 16px; font-size: 13px; }
.tip-card li { padding-left: 4px; margin-bottom: 8px; }
.tip-note { font-size: 11px; color: #665b4b; margin-bottom: 0; }
.record-card { background: #fffdf8; border: 1px solid #d2d8c9; }
.record-card h2 { font-size: 24px; margin-bottom: 10px; }
.record-card > p { font-size: 12px; color: #687063; }
.record-card .storage-note { font-size: 10px; margin-bottom: 0; }
.result-card { background: #dce8d0; border: 1px solid #adbf9a; }
.result-card.is-lost { background: #f0dfd3; border-color: #d3b7a8; }
.result-card p { font-size: 13px; }
.keyboard-note { font-size: 11px; color: #687063; padding: 0 4px; }
.notice { background: #e9c5b4; padding: 16px; }
.bottom-note { margin-top: 44px; padding: 28px 0; border-top: 1px solid #d2d8c9; border-bottom: 1px solid #d2d8c9; display: flex; align-items: center; justify-content: space-between; gap: 22px; }
.bottom-note p { margin-bottom: 0; color: #687063; font-size: 13px; }
.bottom-note .eyebrow { margin-bottom: 8px; font-size: 10px; }
.bottom-note a { font-size: 12px; color: #586157; }
.site-footer { padding: 28px 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px; }
.site-footer .brand { font-size: 23px; }
.site-footer p { font-size: 12px; color: #687063; margin: 0; }
@media (max-width: 840px) { .game-layout { grid-template-columns: minmax(0, 1fr); } .game-sidebar { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); } .keyboard-note, .result-card { grid-column: 1 / -1; } }
@media (max-width: 600px) {
  .container { width: calc(100% - 40px); } .site-header { padding: 18px 20px; min-height: 74px; } .brand { font-size: 24px; }
  .game-heading { padding: 28px 0 24px; } h1 { font-size: 34px; letter-spacing: -1.2px; } .solo-tag { display: none; }
  .scoreboard > div { padding: 0 12px; } .scoreboard strong { font-size: 21px; } .score-label { font-size: 9px; letter-spacing: .5px; }
  .drawing-area { padding: 16px 18px 0; } .drawing { width: 260px; } .drawing-caption .eyebrow { font-size: 9px; letter-spacing: .8px; }
  .word-area { padding: 22px 14px; } .word { gap: 5px; } .letter { width: 27px; height: 38px; font-size: 20px; }
  .keyboard { grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; } .game-sidebar { display: flex; }
  .tip-card, .record-card, .result-card { padding: 22px; } .bottom-note { flex-wrap: wrap; justify-content: flex-start; margin-top: 22px; }
}
@media (max-width: 380px) { .container { width: calc(100% - 28px); } h1 { font-size: 30px; } .drawing-caption { gap: 6px; } }
@media (prefers-reduced-motion: reduce) { .small-button, .primary-button, .key { transition: none; } }

