.scoreboard strong { display: block; font-size: 23px; line-height: 1.3; }
.puzzle-card { background: #fffdf8; border: 1px solid #d2d8c9; border-radius: 9px; overflow: hidden; }
.drawing-area { background: #dce5e9; padding: 18px 24px 0; }
.drawing-caption { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.drawing-caption .eyebrow { margin: 0; color: #47616a; }
.letters-note { font-size: 11px; color: #526973; white-space: nowrap; }
.drawing { display: block; width: 300px; max-width: 100%; height: auto; margin: 4px auto 0; }
.word-area { padding: 24px; }
.word { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
.letter { display: flex; align-items: center; justify-content: center; width: 32px; height: 42px; border-bottom: 2px solid #a9b8a4; background: #f1f3e9; border-radius: 4px 4px 0 0; font-size: 22px; line-height: 1; font-weight: 700; }
.letter.is-known { color: #283d32; background: #e3ecd9; border-color: #8ba17a; }
.letter.is-missing { color: #9e4d37; background: #f3e0d5; border-color: #b87760; }
.game-status { min-height: 40px; margin: 18px 0 0; font-size: 13px; color: #586157; text-align: center; }
.keyboard { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 7px; margin-top: 20px; }
.key { width: 100%; min-width: 0; min-height: 40px; padding: 6px 0; border: 1px solid #bdc8b6; border-radius: 5px; background: #fffdf8; color: #283d32; font-size: 14px; font-weight: 700; transition: background-color .15s ease; }
.key:hover { background: #e6ebdf; }
.key.is-correct, .key.is-correct:hover { color: #355035; background: #dce8d0; border-color: #a8bc98; cursor: default; }
.key.is-wrong, .key.is-wrong:hover { color: #9e4d37; background: #efdfd6; border-color: #d3b7a8; cursor: default; }
.key:disabled { cursor: default; }
.key:disabled:not(.is-correct):not(.is-wrong) { color: #93998d; background: #eeefe6; }
.game-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 18px; }
.hint-note { color: #687063; font-size: 11px; margin: 0; }
.game-sidebar { display: flex; flex-direction: column; gap: 18px; }
.tip-card, .record-card, .result-card { padding: 24px; border-radius: 8px; }
.tip-card { background: #e9c5b4; }
.tip-card h2, .record-card h2, .result-card h2 { font-size: 25px; line-height: 1.2; letter-spacing: -.8px; margin-bottom: 18px; }
.tip-card ol { padding-left: 18px; margin: 0 0 16px; font-size: 13px; }
.tip-card li { padding-left: 4px; margin-bottom: 8px; }
.tip-note { font-size: 11px; color: #665b4b; margin-bottom: 0; }
.record-card { background: #fffdf8; border: 1px solid #d2d8c9; }
.record-card h2 { font-size: 24px; margin-bottom: 10px; }
.record-card > p { font-size: 12px; color: #687063; }
.record-card .storage-note { font-size: 10px; margin-bottom: 0; }
.result-card { background: #dce8d0; border: 1px solid #adbf9a; }
.result-card.is-lost { background: #f0dfd3; border-color: #d3b7a8; }
.result-card p { font-size: 13px; }
.keyboard-note { font-size: 11px; color: #687063; padding: 0 4px; }
.notice { background: #e9c5b4; padding: 16px; }
.bottom-note { margin-top: 44px; padding: 28px 0; border-top: 1px solid #d2d8c9; border-bottom: 1px solid #d2d8c9; display: flex; align-items: center; justify-content: space-between; gap: 22px; }
.bottom-note p { margin-bottom: 0; color: #687063; font-size: 13px; }
.bottom-note .eyebrow { margin-bottom: 8px; font-size: 10px; }
.bottom-note a { font-size: 12px; color: #586157; }
.site-footer { padding: 28px 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px; }
.site-footer .brand { font-size: 23px; }
.site-footer p { font-size: 12px; color: #687063; margin: 0; }
@media (max-width: 840px) { .game-layout { grid-template-columns: minmax(0, 1fr); } .game-sidebar { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); } .keyboard-note, .result-card { grid-column: 1 / -1; } }
@media (max-width: 600px) {
  .container { width: calc(100% - 40px); } .site-header { padding: 18px 20px; min-height: 74px; } .brand { font-size: 24px; }
  .game-heading { padding: 28px 0 24px; } h1 { font-size: 34px; letter-spacing: -1.2px; } .solo-tag { display: none; }
  .scoreboard > div { padding: 0 12px; } .scoreboard strong { font-size: 21px; } .score-label { font-size: 9px; letter-spacing: .5px; }
  .drawing-area { padding: 16px 18px 0; } .drawing { width: 260px; } .drawing-caption .eyebrow { font-size: 9px; letter-spacing: .8px; }
  .word-area { padding: 22px 14px; } .word { gap: 5px; } .letter { width: 27px; height: 38px; font-size: 20px; }
  .keyboard { grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; } .game-sidebar { display: flex; }
  .tip-card, .record-card, .result-card { padding: 22px; } .bottom-note { flex-wrap: wrap; justify-content: flex-start; margin-top: 22px; }
}
@media (max-width: 380px) { .container { width: calc(100% - 28px); } h1 { font-size: 30px; } .drawing-caption { gap: 6px; } }
@media (prefers-reduced-motion: reduce) { .small-button, .primary-button, .key { transition: none; } }
]==]

