      if (target && target.tagName === 'BUTTON') return;
      event.preventDefault(); newRound(); return;
    }
    const letter = event.key.toUpperCase();
    if (letter.length === 1 && keys[letter] && phase === 'playing') { event.preventDefault(); guess(letter, false); }
  });
  newRound();
})();
