(() => {
  'use strict';
  try {
    const records = JSON.parse(localStorage.getItem('spielraum.memory.records.v1') || '{}');
    const best = records && records['8'];
    if (best && Number.isInteger(best.moves) && best.moves >= 8 && Number.isInteger(best.seconds) && best.seconds >= 0) {
      document.getElementById('memory-record').textContent = 'Dein Rekord bei 8 Paaren: ' + best.moves + ' Züge. Schaffst du weniger?';
    }
  } catch (error) {
    // Playing never depends on storage access or the shape of older data.
  }
})();

files.styles.css:
:root { color-scheme: light; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: #f5f2e9; color: #242e28; font: 16px/1.65 Arial, sans-serif; }
a { color: inherit; }
img { display: block; max-width: 100%; height: auto; }
figure { margin: 0; }
.container { width: calc(100% - 96px); max-width: 1160px; margin: 0 auto; }
.skip-link { position: absolute; top: -100px; left: 24px; z-index: 10; background: #242e28; color: #fff; padding: 12px 18px; }
.skip-link:focus { top: 12px; }
a:focus-visible { outline: 3px solid #a14b31; outline-offset: 5px; }
.site-header { min-height: 100px; padding: 24px 48px; display: flex; align-items: center; justify-content: space-between; gap: 24px; border-bottom: 1px solid #d9ddd2; }
.brand { font-size: 28px; font-weight: 700; letter-spacing: -1.2px; text-decoration: none; }
.brand-dot { color: #b45939; }
nav { display: flex; flex-wrap: wrap; gap: 32px; }
nav a { font-size: 14px; font-weight: 700; text-decoration: none; transition: color .18s ease; }
nav a:hover { color: #a14b31; }
.hero { display: grid; grid-template-columns: 1.05fr 1fr; align-items: center; gap: 48px; padding-top: 64px; padding-bottom: 72px; }
