files.app.js:
(() => {
  'use strict';
  const byId = id => document.getElementById(id);
  const board = byId('board');
  const difficulty = byId('difficulty');
  const pauseButton = byId('pause');
  const backgroundMusic = new Audio('https://assetdelivery.roblox.com/v1/asset/?id=117006292434032');
  backgroundMusic.loop = true;
  backgroundMusic.volume = 0.35;
  function startBackgroundMusic() {
    backgroundMusic.play().then(() => {
      document.removeEventListener('pointerdown', startBackgroundMusic);
      document.removeEventListener('keydown', startBackgroundMusic);
    }).catch(error => {
      if (error.name === 'NotAllowedError') {
        document.addEventListener('pointerdown', startBackgroundMusic, { once: true });
        document.addEventListener('keydown', startBackgroundMusic, { once: true });
      } else if (error.name !== 'AbortError') {
        console.warn('Hintergrundmusik konnte nicht starten:', error.name);
      }
    });
  }
  const storageKey = 'spielraum.memory.records.v1';
  const motifs = [
    ['sun', 'Sonne'], ['moon', 'Mond'], ['leaf', 'Blatt'], ['cloud', 'Wolke'],
    ['star', 'Stern'], ['wave', 'Welle'], ['flower', 'Blume'], ['mountain', 'Berg'],
    ['butterfly', 'Falter'], ['shell', 'Muschel'], ['bolt', 'Blitz'], ['heart', 'Herz']
  ];
  let records = {};
  let storageAvailable = true;
  let tiles = [];
  let deck = [];
  let pairCount = 8;
  let found = 0;
  let moves = 0;
  let first = -1;
  let second = -1;
  let phase = 'ready';
  let locked = false;
  let clockTimer = null;
  let flipTimer = null;
  let flipDue = 0;
  let flipRemaining = 850;
  let elapsedBefore = 0;
  let startedAt = 0;
  let generation = 0;
  let shownTime = '';

  function validRecord(value, count) {
    return value && Number.isInteger(value.moves) && value.moves >= count &&
      Number.isInteger(value.seconds) && value.seconds >= 0;
  }
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
    if (saved && typeof saved === 'object') {
      for (const count of [6, 8, 12]) {
        if (validRecord(saved[String(count)], count)) records[String(count)] = saved[String(count)];
      }
    }
  } catch (error) { storageAvailable = false; }

  function setStatus(message) { byId('status').textContent = message; }
  function milliseconds() {
    return elapsedBefore + (phase === 'playing' ? performance.now() - startedAt : 0);
  }
  function formatTime(seconds) {
    const minutes = Math.floor(seconds / 60);
    return String(minutes).padStart(2, '0') + ':' + String(seconds % 60).padStart(2, '0');
  }
  function updateClock() {
    const value = formatTime(Math.floor(milliseconds() / 1000));
    if (value !== shownTime) { shownTime = value; byId('time').textContent = value; }
  }
  function stopClock() {
    if (clockTimer !== null) clearInterval(clockTimer);
    clockTimer = null;
  }
  function runClock() {
    startedAt = performance.now();
    stopClock();
    clockTimer = setInterval(updateClock, 250);
  }
  function updateBest() {
    const best = records[String(pairCount)];
    byId('best-moves').textContent = best ? best.moves + ' Züge' : 'Noch ganz offen.';
    byId('best-detail').textContent = best ? pairCount + ' Paare in ' + formatTime(best.seconds) + '. Weniger Züge zählen zuerst.' : 'Deine erste fertige Runde setzt die Marke.';
    byId('clear-record').hidden = !best;
    byId('storage-note').textContent = storageAvailable ? 'Dein Rekord bleibt für die nächste Runde gespeichert.' : 'Speichern ist gerade nicht verfügbar. Du kannst trotzdem spielen.';
  }
  function paintTile(index) {
    const tile = tiles[index];
    const open = deck[index].matched || index === first || index === second;
    tile.root.classList.toggle('is-open', open);
    tile.root.classList.toggle('is-matched', deck[index].matched);
    tile.button.setAttribute('aria-pressed', String(open));
    tile.button.setAttribute('aria-disabled', String(deck[index].matched || phase === 'paused'));
    tile.button.setAttribute('aria-label', 'Karte ' + (index + 1) + ': ' + (open ? motifs[deck[index].motif][1] : 'verdeckt') + (deck[index].matched ? ', Paar gefunden' : ''));
  }
  function finish() {
    elapsedBefore = milliseconds();
    phase = 'won';
    stopClock();
    updateClock();
    const seconds = Math.floor(elapsedBefore / 1000);
    const old = records[String(pairCount)];
    const improved = !old || moves < old.moves || (moves === old.moves && seconds < old.seconds);
    if (improved) {
      records[String(pairCount)] = { moves, seconds };
      try { localStorage.setItem(storageKey, JSON.stringify(records)); }
      catch (error) { storageAvailable = false; }
    }
    updateBest();
    byId('result-title').textContent = improved ? 'Deine neue Bestmarke.' : 'Gut gemerkt.';
    byId('result-summary').textContent = pairCount + ' Paare, ' + moves + ' Züge und ' + formatTime(seconds) + '. Lust auf eine neue Mischung?';
    byId('result').hidden = false;
    setStatus('Alle ' + pairCount + ' Paare gefunden!' + (improved ? ' Neuer persönlicher Rekord.' : ' Schön gespielt.'));
  }
  function closeMismatch() {
    const a = first, b = second;
    first = -1; second = -1; locked = false; flipTimer = null; flipRemaining = 850;
    paintTile(a); paintTile(b);
    setStatus('Fast. Merk dir die Plätze und versuch das nächste Paar.');
  }
  function scheduleMismatch() {
    const round = generation;
    flipDue = performance.now() + flipRemaining;
    flipTimer = setTimeout(() => {
      if (round === generation && phase === 'playing') closeMismatch();
