  }
  function reveal(index) {
    if (phase === 'paused' || phase === 'won' || locked || deck[index].matched || first === index) return;
    if (phase === 'ready') { phase = 'playing'; runClock(); }
    if (first === -1) {
      first = index; paintTile(index); setStatus('Wo liegt das Gegenstück? Decke eine zweite Karte auf.'); return;
    }
    second = index; moves += 1;
    byId('moves').textContent = String(moves);
    paintTile(index);
    if (deck[first].motif === deck[second].motif) {
      const a = first, b = second;
      deck[a].matched = true; deck[b].matched = true;
      first = -1; second = -1; found += 1;
      paintTile(a); paintTile(b);
      byId('pairs').textContent = found + ' / ' + pairCount;
      if (found === pairCount) finish();
      else setStatus('Ein Paar! Noch ' + (pairCount - found) + ' warten auf dich.');
    } else { locked = true; flipRemaining = 850; setStatus('Zwei verschiedene Motive. Einen Moment zum Merken …'); scheduleMismatch(); }
  }
  function togglePause() {
    if (phase === 'ready') { setStatus('Deine Uhr startet erst mit der ersten Karte.'); return; }
    if (phase === 'won') return;
