  }
  function createTile(index) {
    const root = document.createElement('div'); root.className = 'tile';
    const face = document.createElement('div'); face.className = 'tile-face'; face.setAttribute('aria-hidden', 'true');
    const image = document.createElement('img'); image.alt = ''; image.width = 48; image.height = 48;
    const name = document.createElement('span'); name.className = 'tile-name';
    face.append(image, name);
    const button = document.createElement('button'); button.type = 'button'; button.className = 'tile-button';
    const back = document.createElement('div'); back.className = 'tile-back'; back.setAttribute('aria-hidden', 'true');
    const spark = document.createElement('img'); spark.alt = ''; spark.width = 32; spark.height = 32; spark.setAttribute('src', 'assets/spark.svg');
    back.append(spark);
    button.addEventListener('click', () => reveal(index));
    root.append(face, button, back); board.append(root);
    return { root, image, name, button };
  }
  function newRound() {
    generation += 1; stopClock();
    if (flipTimer !== null) clearTimeout(flipTimer);
    flipTimer = null; locked = false; phase = 'ready'; first = -1; second = -1;
    found = 0; moves = 0; elapsedBefore = 0; flipRemaining = 850; shownTime = '';
    pairCount = Number(difficulty.value);
    if (![6, 8, 12].includes(pairCount)) { pairCount = 8; difficulty.value = '8'; }
    deck = [];
    for (let i = 0; i < pairCount; i += 1) { deck.push({ motif: i, matched: false }, { motif: i, matched: false }); }
    for (let i = deck.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      const value = deck[i]; deck[i] = deck[j]; deck[j] = value;
    }
    board.setAttribute('data-size', String(deck.length)); board.removeAttribute('inert');
    if (tiles.length !== deck.length) {
      board.replaceChildren(); tiles = [];
      for (let i = 0; i < deck.length; i += 1) tiles.push(createTile(i));
    }
    for (let i = 0; i < deck.length; i += 1) {
      const motif = motifs[deck[i].motif];
