  byId('restart').addEventListener('click', newRound);
  byId('play-again').addEventListener('click', () => { newRound(); tiles[0].button.focus(); });
  pauseButton.addEventListener('click', togglePause);
  byId('resume').addEventListener('click', togglePause);
  byId('clear-record').addEventListener('click', () => {
    delete records[String(pairCount)];
    try { localStorage.setItem(storageKey, JSON.stringify(records)); }
    catch (error) { storageAvailable = false; }
    updateBest();
    setStatus('Deine Bestmarke für ' + pairCount + ' Paare ist zurückgesetzt. Die aktuelle Runde bleibt erhalten.');
  });
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && (phase === 'playing' || phase === 'paused')) { event.preventDefault(); togglePause(); }
  });
