:root { color-scheme: light; }
* { box-sizing: border-box; }
body { margin: 0; background: #f5f2e9; color: #242e28; font: 15px/1.6 Arial, sans-serif; }
a { color: inherit; }
button, select { font: inherit; }
button { cursor: pointer; }
[hidden] { display: none !important; }
.container { width: calc(100% - 96px); max-width: 1080px; margin: 0 auto; }
.skip-link { position: absolute; left: 20px; top: -100px; z-index: 20; background: #283d32; color: #fff; padding: 12px 18px; }
.skip-link:focus { top: 12px; }
a:focus-visible, button:focus-visible, select:focus-visible { outline: 3px solid #a14b31; outline-offset: 4px; }
.site-header { min-height: 84px; padding: 20px 48px; display: flex; align-items: center; justify-content: space-between; gap: 20px; border-bottom: 1px solid #d9ddd2; }
.brand { font-size: 28px; font-weight: 700; letter-spacing: -1.2px; text-decoration: none; }
.brand-dot { color: #b45939; }
.back-link { color: #586157; font-size: 13px; text-decoration: none; }
.back-link:hover { color: #a14b31; }
h1, h2, p { margin-top: 0; }
.eyebrow { font-size: 10px; letter-spacing: 1.7px; text-transform: uppercase; font-weight: 700; margin: 0 0 12px; }
.game-heading { padding: 34px 0 28px; display: flex; justify-content: space-between; gap: 24px; align-items: center; }
h1 { font-size: 44px; line-height: 1.12; letter-spacing: -1.8px; margin-bottom: 12px; }
.intro { color: #687063; font-size: 14px; margin-bottom: 0; max-width: 550px; }
.solo-tag { border: 1px solid #cdd4c7; border-radius: 22px; padding: 5px 12px; color: #687063; font-size: 11px; white-space: nowrap; }
.game-layout { display: grid; grid-template-columns: minmax(0, 1fr) 260px; gap: 36px; align-items: start; }
.toolbar { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px; margin-bottom: 20px; }
.difficulty-label { font-size: 11px; color: #687063; }
select { display: block; background: #fffdf8; color: #283d32; border: 1px solid #bdc8b6; border-radius: 5px; padding: 8px 10px; min-width: 168px; margin-top: 5px; font-size: 13px; height: 38px; }
.toolbar-actions { display: flex; gap: 8px; }
.restart-wrap { position: relative; display: inline-block; }
.restart-wrap button { padding-right: 32px; }
.restart-icon { position: absolute; right: 11px; top: 50%; transform: translateY(-50%); width: 14px; height: 14px; pointer-events: none; }
.small-button { background: #fffdf8; color: #283d32; border: 1px solid #bdc8b6; padding: 8px 12px; border-radius: 5px; min-height: 38px; font-size: 12px; transition: background-color .15s ease; }
.small-button:hover { background: #e6ebdf; }
.primary-button { background: #283d32; color: #fff8e9; border: 1px solid #283d32; padding: 12px 18px; border-radius: 5px; font-size: 13px; transition: background-color .15s ease; }
.primary-button:hover { background: #3d5446; }
.scoreboard { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border: 1px solid #d2d8c9; border-radius: 7px; background: #fffdf8; margin-bottom: 20px; padding: 12px 0; }
.scoreboard > div { padding: 0 18px; }
.scoreboard > div + div { border-left: 1px solid #e2e6d9; }
.score-label { display: block; color: #687063; font-size: 10px; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 2px; }
.scoreboard strong { display: block; font-size: 23px; line-height: 1.3; }
.board-stage { position: relative; }
.board { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.tile { position: relative; width: 100%; aspect-ratio: 1 / 1; min-width: 0; }
.tile-face { position: absolute; inset: 0; border: 1px solid #d4cbae; border-radius: 9px; background: #fff8df; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 6px; opacity: 0; transform: scale(.96); transition: opacity .16s ease, transform .16s ease; pointer-events: none; }
.tile-face img { display: block; width: 48px; height: 48px; }
.tile-name { font-size: 11px; color: #526044; }
.tile-button { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 1px solid #6d5d9f; border-radius: 9px; background: #8170b6; color: #f9f4e8; font-size: 34px; line-height: 1; transition: background-color .15s ease; }
.tile-button:hover { background: #7261a5; }
.tile-back { position: absolute; inset: 0; z-index: 1; display: flex; justify-content: center; align-items: center; pointer-events: none; opacity: 1; }
.tile-back img { display: block; width: 32px; height: 32px; }
.tile.is-open .tile-back { opacity: 0; }
.tile.is-open .tile-face { opacity: 1; transform: scale(1); }
.tile.is-open .tile-button { background: transparent; border-color: transparent; }
.tile.is-matched .tile-face { background: #e2eddb; border-color: #adbf9a; }
.tile.is-matched .tile-button { cursor: default; }
.pause-cover { position: absolute; inset: 0; z-index: 5; background: #e3e8da; border: 1px solid #bac9ad; border-radius: 9px; display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 24px; text-align: center; }
.pause-cover h2 { font-size: 34px; margin-bottom: 8px; }
.pause-cover > p { color: #586157; }
.game-status { min-height: 44px; padding-top: 14px; font-size: 12px; color: #586157; margin-bottom: 12px; }
.game-sidebar { display: flex; flex-direction: column; gap: 18px; }
.tip-card, .record-card, .result-card { padding: 24px; border-radius: 8px; }
.tip-card { background: #e9c5b4; }
.tip-card h2, .record-card h2, .result-card h2 { font-size: 25px; line-height: 1.2; letter-spacing: -.8px; margin-bottom: 18px; }
.tip-card ol { padding-left: 18px; margin: 0 0 16px; font-size: 13px; }
.tip-card li { padding-left: 4px; margin-bottom: 8px; }
.tip-note { font-size: 11px; color: #665b4b; margin-bottom: 0; }
.record-card { background: #fffdf8; border: 1px solid #d2d8c9; }
.record-card h2 { font-size: 24px; margin-bottom: 10px; }
.record-card > p { font-size: 12px; color: #687063; }
.record-card .small-button { margin-bottom: 14px; }
.record-card .storage-note { font-size: 10px; margin-bottom: 0; }
.result-card { background: #dce8d0; border: 1px solid #adbf9a; }
.result-card p { font-size: 13px; }
.keyboard-note { font-size: 11px; color: #687063; padding: 0 4px; }
.notice { background: #e9c5b4; padding: 16px; }
.bottom-note { margin-top: 44px; padding: 28px 0; border-top: 1px solid #d2d8c9; border-bottom: 1px solid #d2d8c9; display: flex; align-items: center; justify-content: space-between; gap: 22px; }
.note-spark { display: block; width: 32px; height: 32px; }
.bottom-note p { margin: 0; color: #687063; font-size: 13px; }
.bottom-note a { font-size: 12px; color: #586157; }
.site-footer { padding: 28px 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px; }
.site-footer .brand { font-size: 23px; }
.site-footer p { font-size: 12px; color: #687063; margin: 0; }
@media (min-width: 600px) { .board[data-size="24"] { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
@media (max-width: 840px) { .game-layout { grid-template-columns: minmax(0, 1fr); } .game-sidebar { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); } .keyboard-note { grid-column: 1 / -1; } .result-card { grid-column: 1 / -1; } }
@media (max-width: 600px) {
  .container { width: calc(100% - 40px); } .site-header { padding: 18px 20px; min-height: 74px; } .brand { font-size: 24px; }
  .game-heading { padding: 28px 0 24px; } h1 { font-size: 34px; letter-spacing: -1.2px; } .solo-tag { display: none; }
  .board { gap: 8px; } .tile-face { gap: 3px; border-radius: 7px; } .tile-button { border-radius: 7px; font-size: 28px; }
  .tile-face img { width: 36px; height: 36px; } .tile-name { font-size: 9px; }
  .tile-back img { width: 26px; height: 26px; }
  .scoreboard > div { padding: 0 12px; } .scoreboard strong { font-size: 21px; }
  .game-sidebar { display: flex; } .tip-card, .record-card, .result-card { padding: 22px; }
  .bottom-note { flex-wrap: wrap; justify-content: flex-start; margin-top: 22px; }
}
@media (max-width: 380px) { .container { width: calc(100% - 28px); } h1 { font-size: 30px; } .tile-face img { width: 28px; height: 28px; } .tile-name { font-size: 8px; } }
@media (prefers-reduced-motion: reduce) { .tile-face, .tile-button, .small-button, .primary-button { transition: none; } }

