let popup = null;
let tabCount = 0;
const compact = location.search.indexOf('view=') !== -1;
const tabView = location.search.indexOf('view=tab') !== -1;
function element(id) { return document.getElementById(id); }
function report(id, text) { element(id).textContent = text; }
function click(id, action) { element(id).addEventListener('click', action); }
function attempt(id, action) {
  try { action(); } catch (error) { report(id, 'Aktion fehlgeschlagen: ' + error.message); }
}
function pageURL(view) { return location.href.split('?')[0].split('#')[0] + '?view=' + view; }
function withPopup(action) {
  if (!popup || popup.closed) { report('popup-status', 'Bitte zuerst ein Zusatzfenster öffnen.'); return; }
  attempt('popup-status', function () { action(popup); });
}
function describePopup() {
  if (!popup) { report('popup-status', 'Noch kein Zusatzfenster geöffnet.'); return; }
  if (popup.closed) { report('popup-status', 'Das Zusatzfenster ist geschlossen.'); return; }
  report('popup-status', 'Geöffnet · Position ' + popup.screenX + ' / ' + popup.screenY + ' · äußere Größe ' + popup.outerWidth + ' × ' + popup.outerHeight);
}
if (compact) {
  element('overview').hidden = true;
  element('companion').hidden = false;
  document.title = tabView ? 'Testtab' : 'Zusatzfenster';
  report('companion-title', document.title);
  report('companion-description', tabView ? 'Ziehe diesen Tab an eine andere Position oder schließe ihn mit dem Tab-Kreuz.' : 'Dieses benannte Fenster lässt sich vom Hauptfenster aus wiederverwenden und steuern.');
}
click('open-tab', function () {
  attempt('tab-status', function () {
    const tab = window.open(pageURL('tab'), '_blank');
    if (!tab) { report('tab-status', 'Der Host hat die Anfrage blockiert oder unterstützt keine Zusatzfenster.'); return; }
    tabCount += 1;
    report('tab-status', 'Tab angefordert (' + tabCount + '). Prüfe die Animation und die Tab-Leiste.');
  });
});
click('open-popup', function () {
  attempt('popup-status', function () {
    popup = window.open(pageURL('popup'), 'fenstercheck', 'popup,width=460,height=400,left=80,top=100');
    if (!popup) { report('popup-status', 'Das Fenster wurde blockiert oder der Host unterstützt keine Zusatzfenster.'); return; }
    popup.focus();
    describePopup();
  });
});
click('focus-popup', function () { withPopup(function (win) { win.focus(); report('popup-status', 'Fokus angefordert. Prüfe, ob das Zusatzfenster vorne liegt.'); }); });
click('move-popup', function () { withPopup(function (win) { win.moveBy(25, 15); describePopup(); }); });
click('resize-popup', function () { withPopup(function (win) { win.resizeTo(520, 420); describePopup(); }); });
click('check-popup', function () { attempt('popup-status', describePopup); });
click('close-popup', function () { withPopup(function (win) { win.close(); report('popup-status', 'Schließen angefordert. Über „Zustand lesen“ kannst du nach einer Schutzabfrage erneut prüfen.'); }); });
click('show-alert', function () {
  attempt('dialog-status', function () { alert('Eine Meldung aus dem Fenstercheck.'); report('dialog-status', 'Meldung geschlossen. Der Code läuft erst danach weiter.'); });
});
click('show-confirm', function () {
  attempt('dialog-status', function () { const answer = confirm('Soll dieser Test bestätigt werden?'); report('dialog-status', 'Rückgabewert: ' + answer); });
});
click('show-prompt', function () {
  attempt('dialog-status', function () { const answer = prompt('Ein Text für den Test:', 'Meine Notiz'); report('dialog-status', answer === null ? 'Abgebrochen: null' : 'Bestätigter Text: „' + answer + '“'); });
});
element('leave-guard').addEventListener('change', function () {
  report('guard-status', this.checked ? 'Schutz ist an. Probiere Reload oder Schließen und wähle „Bleiben“.' : 'Schutz ist aus.');
});
element('companion-guard').addEventListener('change', function () {
  report('companion-status', this.checked ? 'Schließen-Schutz ist an.' : 'Schließen-Schutz ist aus.');
});
window.addEventListener('beforeunload', function (event) {
  const guarded = compact ? element('companion-guard').checked : element('leave-guard').checked;
  if (guarded) { event.preventDefault(); event.returnValue = ''; }
});
click('reload-page', function () { location.reload(); });
click('focus-opener', function () {
  attempt('companion-status', function () {
    if (!window.opener || window.opener.closed) { report('companion-status', 'Kein geöffnetes Hauptfenster verfügbar.'); return; }
