document.addEventListener('visibilitychange', visibility);
visibility();

const permissionStates = {};
let mediaStream = null;
let mediaGeneration = 0;
const cameraPreview = document.getElementById('camera-preview');
function stopMedia() {
  mediaGeneration += 1;
  if (mediaStream) mediaStream.getTracks().forEach(function (track) { track.stop(); });
  mediaStream = null;
  cameraPreview.pause();
  cameraPreview.srcObject = null;
}
function renderPermissions() {
  const names = ['camera', 'microphone'];
  report('permission-state', names.map(function (name) {
    return (name === 'camera' ? 'Kamera' : 'Mikrofon') + ': ' + (permissionStates[name] ? permissionStates[name].state : 'unbekannt');
  }).join(' · '));
}
function permissionStatus() {
  if (typeof navigator === 'undefined' || !navigator.permissions) {
    report('permission-state', 'Dieser Host stellt keine Berechtigungsabfrage bereit.'); return;
  }
  const names = ['camera', 'microphone'];
  const results = names.map(function (name) {
    if (permissionStates[name]) return Promise.resolve(permissionStates[name]);
    return navigator.permissions.query({ name: name }).then(function (status) {
      permissionStates[name] = status;
      status.onchange = renderPermissions;
      return status;
    });
  });
  Promise.all(results).then(renderPermissions, function (error) { report('permission-state', error.name + ': ' + error.message); });
}
function requestMedia(constraints) {
  if (typeof navigator === 'undefined' || !navigator.mediaDevices || typeof navigator.mediaDevices.getUserMedia !== 'function') {
    report('permission-status', 'Dieser Host unterstützt getUserMedia nicht.'); return;
  }
  report('permission-status', 'Die Berechtigungsanfrage läuft. Bitte im Fenster antworten.');
  const generation = ++mediaGeneration;
  navigator.mediaDevices.getUserMedia(constraints).then(function (stream) {
    if (generation !== mediaGeneration) { stream.getTracks().forEach(function (track) { track.stop(); }); return; }
    if (mediaStream) mediaStream.getTracks().forEach(function (track) { track.stop(); });
    mediaStream = stream;
    cameraPreview.srcObject = stream;
    const track = stream.getVideoTracks()[0];
    if (track) track.addEventListener('ended', function () {
      if (mediaStream === stream) report('permission-status', 'Die Kameraquelle ist nicht mehr verfügbar.');
    });
    report('permission-status', 'Kamera freigegeben. Das Livebild läuft.');
    cameraPreview.play().catch(function (error) {
      if (mediaStream === stream) report('permission-status', error.name + ': ' + error.message);
    });
    permissionStatus();
  }, function (error) {
    if (generation !== mediaGeneration) return;
    report('permission-status', error.name + ': ' + error.message);
    permissionStatus();
  });
}
click('ask-camera', function () { requestMedia({ video: true }); });
click('stop-camera', function () { stopMedia(); report('permission-status', 'Kamera gestoppt.'); });
click('ask-microphone', function () { requestMedia({ audio: true }); });
click('ask-media', function () { requestMedia({ video: true, audio: true }); });
click('permission-check', permissionStatus);

