header { margin-bottom: 28px; }
h1 { margin: 4px 0 10px; font-size: 34px; line-height: 1.2; }
h2 { margin: 0 0 12px; font-size: 21px; line-height: 1.35; }
p { margin: 10px 0; }
.eyebrow { color: #64717e; font-size: 12px; letter-spacing: 1px; text-transform: uppercase; }
section { margin: 18px 0; padding: 22px; background: #fff; border: 1px solid #d6dce2; border-radius: 6px; }
ol { padding-left: 22px; margin: 10px 0; }
li { margin: 8px 0; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
button { padding: 8px 12px; border: 1px solid #aab6c1; border-radius: 4px; background: #f6f8fa; color: #26323e; font: inherit; cursor: pointer; }
button:hover { background: #e8eef4; border-color: #788b9f; }
button:active { background: #d5e0eb; }
button:focus-visible, input:focus-visible, summary:focus-visible { outline: 2px solid #346ca5; outline-offset: 3px; }
label { display: block; margin-top: 10px; font-weight: bold; }
input[type="text"] { display: block; width: 100%; padding: 9px 10px; margin: 6px 0 14px; border: 1px solid #aab6c1; border-radius: 3px; background: #fff; color: #26323e; font: inherit; }
.check { font-weight: normal; }
.check input { margin-right: 6px; }
.status { padding: 9px 11px; background: #eef3f7; border-left: 3px solid #718da7; }
.hint, footer { color: #60707e; font-size: 13px; }
details { margin-top: 14px; border-top: 1px solid #d6dce2; padding-top: 12px; }
summary { cursor: pointer; font-weight: bold; }
summary:hover { color: #245b91; }
#fullscreen-panel:fullscreen { width: 100%; height: 100%; margin: 0; padding: 36px; border-radius: 0; background: #fff; overflow: auto; }
#companion { max-width: 640px; padding-top: 24px; }
#camera-preview { display: block; width: 100%; max-width: 640px; height: auto; margin-top: 16px; background: #151a20; }
[hidden] { display: none; }
@media (max-width: 520px) { main { padding: 22px 14px 36px; } section { padding: 17px; } h1 { font-size: 29px; } }
